WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND active_dispatch_key IS NULL

SELECT COUNT(*) FROM quant_order_dispatch_ticket
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND idempotency_key=#{key}

SELECT dispatch_status FROM quant_order_dispatch_ticket
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND idempotency_key=#{key} AND client_order_id=#{clientOrderId}
  AND strategy_instance_id=#{instanceId} AND operation_type='OPEN'
LIMIT 1
